/** Settings patches: any stored setting, by the dot paths of the committed
 * catalog (`settingCatalog.json`, regenerated by `pnpm settings:catalog`).
 * Objects deep-merge; lists replace whole. Every refusal is a problem and
 * nothing is applied unless there are none. Pure: no store, no server. */

import { migrateShareValue } from "./channelConfig"
import type { SpecProblem } from "./chartSpec"
import { newComposedLabelId } from "./dataLabelsSelection"
import { didYouMean } from "./didYouMean"
import { foldFlowNodeTitles } from "./foldFlowNodeTitles"
import { formatSpecProblem } from "./formatTick"
import { COUNTRY_NAME_FORMAT } from "./geo/countryNames"
import { structureVisualKeys } from "./savedKeyStructure"
import catalogJson from "./settingCatalog.json"
import type { Visual } from "./types"

export type SettingKind = "string" | "number" | "boolean" | "null" | "list" | "object"

/** A value's declared type; no `kinds` = anything goes. */
export type SettingType = { kinds?: SettingKind[]; values?: string[]; items?: SettingType }

export type SettingEntry = SettingType & {
	doc?: string
	/** Holds a color (hex). */
	color?: boolean
	/** Holds a Format-box string (d3-format / d3-time-format). */
	format?: boolean
}

export const SETTING_CATALOG = catalogJson as {
	slices: string[]
	paths: Record<string, SettingEntry>
}

export type ApplySettingsOptions = {
	/** A fresh id for a new entry of the list at `listPath` (a catalog path
	 *  such as `annotationsConfig.texts`). Defaults to the editor's minting. */
	mintId?: (listPath: string) => string
}

const minted = (prefix: string) =>
	`${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 6)}`

/** The prefixes the sidebar's add handlers mint with. */
const ID_PREFIX: Record<string, string> = {
	"annotationsConfig.rectangles": "rect",
	"annotationsConfig.circles": "circle",
	"annotationsConfig.lineSegments": "line",
	"annotationsConfig.texts": "text",
}

const defaultMintId = (listPath: string) =>
	listPath === "dataLabelsConfig.composedLabels"
		? newComposedLabelId()
		: minted(ID_PREFIX[listPath] ?? "item")

/** `|` and control characters never go into a saved key (CLAUDE.md: the
 * hosting firewall inspects stored content). */
const unsafeKey = (key: string): boolean => {
	for (let i = 0; i < key.length; i++) {
		const c = key.charCodeAt(i)
		if (c < 0x20 || c === 0x7f || c === 0x7c) return true
	}
	return false
}

const isObj = (v: unknown): v is Record<string, unknown> =>
	typeof v === "object" && v !== null && !Array.isArray(v)

const kindOf = (v: unknown): SettingKind | "other" => {
	if (v === null) return "null"
	if (Array.isArray(v)) return "list"
	if (isObj(v)) return "object"
	if (typeof v === "string") return "string"
	if (typeof v === "boolean") return "boolean"
	return typeof v === "number" && Number.isFinite(v) ? "number" : "other"
}

let childIndex: Map<string, string[]> | null = null
/** Catalog path → the member names one segment below it. */
const childrenOf = (path: string): string[] => {
	if (!childIndex) {
		childIndex = new Map()
		for (const p of Object.keys(SETTING_CATALOG.paths)) {
			const dot = p.lastIndexOf(".")
			if (dot === -1) continue
			const parent = p.slice(0, dot)
			const list = childIndex.get(parent) ?? []
			list.push(p.slice(dot + 1))
			childIndex.set(parent, list)
		}
	}
	return childIndex.get(path) ?? []
}

const describeKinds = (t: SettingType) =>
	(t.kinds ?? [])
		.map((k) => (k === "string" && t.values ? t.values.map((v) => `"${v}"`).join(" | ") : k))
		.join(" or ")

/** The facet per-panel range maps, with how many panel keys deep their
 * entries sit (wrap: panel; grid: row, then column). */
const PANEL_RANGE_MAPS = { panelAxisOverrides: 1, gridPanelAxisOverrides: 2 } as const
/** The axes the entries `levels` keys below `map` bound. */
const boundAxes = (map: unknown, levels: number, out: Set<"x" | "y">): void => {
	if (!isObj(map)) return
	for (const v of Object.values(map)) {
		if (levels > 1) boundAxes(v, levels - 1, out)
		else if (isObj(v))
			for (const k of Object.keys(v)) {
				if (/^[xy](Min|Max|Ticks)$/.test(k)) out.add(k[0] as "x" | "y")
			}
	}
}

/** Apply `patch` (slice → value, merged by the catalog's types) to `visual`.
 * Any problem returns the visual unchanged. */
export const applySettings = (
	visual: Visual,
	patch: Record<string, unknown>,
	opts: ApplySettingsOptions = {}
): { visual: Visual; problems: SpecProblem[] } => {
	const problems: SpecProblem[] = []
	const bad = (path: string, message: string) => problems.push({ path, message })
	const mintId = opts.mintId ?? defaultMintId
	const { paths, slices } = SETTING_CATALOG

	/** `value` checked against `type` (declared at catalog path `at`, real
	 *  path `real`) and merged into `base`. */
	const merge = (base: unknown, value: unknown, type: SettingType, at: string, real: string): unknown => {
		const kind = kindOf(value)
		if (type.kinds && !type.kinds.includes(kind as SettingKind)) {
			bad(real, `must be ${describeKinds(type)}`)
			return base
		}
		if (kind === "string" && type.values && !type.values.includes(value as string)) {
			bad(real, `must be ${describeKinds(type)}`)
			return base
		}
		if (kind === "string" && (paths[at] as SettingEntry | undefined)?.format) {
			const why = formatSpecProblem(value as string, [COUNTRY_NAME_FORMAT])
			if (why) bad(real, why)
			return value
		}
		if (kind === "list") return replaceList(value as unknown[], type, at, real)
		if (kind !== "object") return value
		const next: Record<string, unknown> = isObj(base) ? { ...base } : {}
		for (const [key, v] of Object.entries(value as Record<string, unknown>)) {
			const named = paths[`${at}.${key}`]
			const entry = named ?? paths[`${at}.*`]
			const child = named ? `${at}.${key}` : `${at}.*`
			const where = `${real}.${key}`
			if (!entry) {
				const names = childrenOf(at).filter((n) => n !== "*")
				bad(where, `unknown setting "${key}"${didYouMean(key, names)}`)
			} else if (!named && unsafeKey(key)) {
				bad(where, `a key can't contain "|" or a control character`)
			} else next[key] = merge(next[key], v, entry, child, where)
		}
		return next
	}

	/** A list replaces the stored one whole. An entry without an id gets a
	 *  fresh one when the list's entries carry ids. */
	const replaceList = (list: unknown[], type: SettingType, at: string, real: string): unknown[] => {
		const element = type.items ?? {}
		const hasId = paths[`${at}[].id`] !== undefined
		const seen = new Set<string>()
		const out: unknown[] = []
		list.forEach((item, i) => {
			let v = merge(undefined, item, element, `${at}[]`, `${real}[${i}]`)
			if (hasId && isObj(v)) {
				if (typeof v.id !== "string" || v.id === "") v = { ...v, id: mintId(at) }
				const id = (v as { id: string }).id
				if (seen.has(id)) bad(`${real}[${i}].id`, `"${id}" is used by another entry`)
				seen.add(id)
			}
			out.push(v)
		})
		return out
	}

	const next: Record<string, unknown> = { ...visual }
	for (const [slice, value] of Object.entries(patch)) {
		if (!slices.includes(slice)) {
			bad(slice, `unknown settings slice "${slice}"${didYouMean(slice, slices)}`)
			continue
		}
		next[slice] = merge(next[slice], value, paths[slice], slice, slice)
	}

	// Per-panel ranges draw only on an unshared axis (the Facet panel
	// offers them there); refuse rather than flip the share setting.
	const facetPatch = isObj(patch.channelConfigs) ? patch.channelConfigs.facet : undefined
	if (isObj(facetPatch) && problems.length === 0) {
		const facet = (next.channelConfigs as Visual["channelConfigs"]).facet
		for (const [map, levels] of Object.entries(PANEL_RANGE_MAPS)) {
			const axes = new Set<"x" | "y">()
			boundAxes(facetPatch[map], levels, axes)
			for (const axis of axes) {
				const key = axis === "x" ? "shareX" : "shareY"
				const share = migrateShareValue(facet?.[key])
				if (share !== "none")
					bad(
						`channelConfigs.facet.${map}`,
						`per-panel ${axis} ranges apply only while "channelConfigs.facet.${key}" is "none" (it is "${share}")`
					)
			}
		}
	}
	if (problems.length > 0) return { visual, problems }
	return { visual: foldFlowNodeTitles(structureVisualKeys(next as Visual)), problems }
}
